+fn montgomery_mul(a: [u64; 4], b: [u64; 4]) -> [u64; 4] {
+    // Interleaved (CIOS) multiplication and reduction; the running value
+    // stays below 2n, so five words suffice.
+    let (mut t0, mut t1, mut t2, mut t3, mut t4) = (0u64, 0u64, 0u64, 0u64, 0u64);
+    for &bi in &b {
+        let (w0, carry) = mac(t0, a[0], bi, 0);
+        let (w1, carry) = mac(t1, a[1], bi, carry);
+        let (w2, carry) = mac(t2, a[2], bi, carry);
+        let (w3, carry) = mac(t3, a[3], bi, carry);
+        let (w4, w5) = adc(t4, carry, 0);
+
+        let k = w0.wrapping_mul(MODULUS_INV);
+        let carry = low_word_carry(w0, k);
+        let (w1, carry) = mac(w1, k, MODULUS[1], carry);
+        let (w2, carry) = mac(w2, k, MODULUS[2], carry);
+        let (w3, carry) = mac(w3, k, MODULUS[3], carry);
+        let (w4, carry) = adc(w4, 0, carry);
+
+        (t0, t1, t2, t3, t4) = (w1, w2, w3, w4, w5 + carry);
+    }
+
+    reduce_wide([t0, t1, t2, t3, t4])
+}

